import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/board/draw-pen-popover.png",i="/docs/images/board/draw-more-tools-mobile.png",k=JSON.parse('{"title":"Draw on a board","description":"Sketch on a board with the marker and highlighter, erase strokes, select with a lasso, and point with the laser.","frontmatter":{"title":"Draw on a board","description":"Sketch on a board with the marker and highlighter, erase strokes, select with a lasso, and point with the laser.","type":"how-to"},"headers":[],"relativePath":"board/draw.md","filePath":"board/draw.md"}'),n={name:"board/draw.md"};function h(l,e,d,c,g,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="draw-on-a-board" tabindex="-1">Draw on a board <a class="header-anchor" href="#draw-on-a-board" aria-label="Permalink to &quot;Draw on a board&quot;">​</a></h1><p>Sketch on a board with the marker and highlighter, erase strokes, select with a lasso, and point with the laser.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need <strong>Editor</strong> access. A viewer link can&#39;t draw.</li><li>Drawing works on a phone: draw with one finger, and use two fingers to pinch-zoom.</li></ul></div><h2 id="draw-with-the-marker-or-highlighter" tabindex="-1">Draw with the marker or highlighter <a class="header-anchor" href="#draw-with-the-marker-or-highlighter" aria-label="Permalink to &quot;Draw with the marker or highlighter&quot;">​</a></h2><ol><li>Click empty canvas so nothing is selected.</li><li>Press <code>M</code> for the marker or <code>Shift+M</code> for the highlighter. Or click <strong>Marker</strong> (the pen icon) in the tool dock.</li><li>To change the pen, color, or width, click the arrow next to <strong>Marker</strong> (<strong>Pen, colour and width</strong>). Pick <strong>Marker</strong> or <strong>Highlighter</strong>, one of eight colors, and <strong>Thin</strong>, <strong>Medium</strong>, or <strong>Thick</strong>.</li><li>Drag on the canvas to draw. Hold <code>Shift</code> while drawing for a straight line.</li><li>Press <code>Escape</code> when you finish.</li></ol><p>The pen stays on stroke after stroke until you press <code>Escape</code>. The highlighter is wide and see-through, so text beneath it stays readable. Your pen choice is remembered in this browser. Teammates see your stroke while you draw it.</p><p><img src="'+s+'" alt="Pen popover with Marker, Highlighter, eight colors, three widths, and Smart shapes"></p><h2 id="turn-sketches-into-clean-shapes" tabindex="-1">Turn sketches into clean shapes <a class="header-anchor" href="#turn-sketches-into-clean-shapes" aria-label="Permalink to &quot;Turn sketches into clean shapes&quot;">​</a></h2><ol><li>Click the arrow next to <strong>Marker</strong> (<strong>Pen, colour and width</strong>).</li><li>Click <strong>Smart shapes</strong> so it reads <strong>On</strong>.</li><li>Draw a box, a circle, a straight line, or a line with an arrowhead.</li></ol><p>The marker stroke becomes a rectangle, an ellipse, a line, or an arrow. A stroke it can&#39;t recognize stays as drawn. Smart shapes work with the marker only, not the highlighter. Pressing <code>⌘+Z</code> / <code>Ctrl+Z</code> removes the shape; to keep a sketch as drawn, turn <strong>Smart shapes</strong> off before you draw it.</p><h2 id="erase-strokes" tabindex="-1">Erase strokes <a class="header-anchor" href="#erase-strokes" aria-label="Permalink to &quot;Erase strokes&quot;">​</a></h2><ol><li>Press <code>Shift+E</code>, or click <strong>Eraser</strong> in the tool dock.</li><li>Drag across the strokes you want to remove. Each stroke you touch is deleted whole.</li><li>Press <code>Escape</code> when you finish.</li></ol><p>The eraser removes only marker and highlighter strokes. To delete anything else, select it and press <code>Delete</code>.</p><h2 id="select-with-the-lasso" tabindex="-1">Select with the lasso <a class="header-anchor" href="#select-with-the-lasso" aria-label="Permalink to &quot;Select with the lasso&quot;">​</a></h2><p>Hold <code>Option</code> / <code>Alt</code> and drag a loop around items on empty canvas. Or click <strong>Lasso select</strong> in the tool dock, then drag. Every item inside the loop is selected.</p><h2 id="point-with-the-laser" tabindex="-1">Point with the laser <a class="header-anchor" href="#point-with-the-laser" aria-label="Permalink to &quot;Point with the laser&quot;">​</a></h2><ol><li>Press <code>Shift+K</code>, or click <strong>Laser pointer</strong> in the top toolbar. On a phone, tap <strong>Facilitate</strong> in the top toolbar, then <strong>Laser pointer</strong>.</li><li>Drag to draw a red trail that everyone on the board sees.</li></ol><p>The trail fades after about a second and a half. Nothing is saved to the board. Press <code>Escape</code> to turn the laser off.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p><strong>Marker</strong> and its arrow stay in the compact tool dock. <strong>Eraser</strong> and <strong>Lasso select</strong> are under <strong>More tools</strong> (the ⋯ button). With the marker on, one finger draws and two fingers pinch to zoom. Tap <strong>Select</strong> to go back to moving items.</p><p><img src="'+i+'" alt="Phone dock with More tools open: Lasso, Hand, Line, Eraser, Section, Insert image, Stamp, and Comment"></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/board/stickies-shapes-connectors.html">Stickies, shapes, and connectors</a> for shapes you place from a menu.</li><li><a href="/docs/board/facilitate-a-session.html">Facilitate a session</a> to run a live session with the laser and spotlight.</li><li><a href="/docs/board/keyboard-shortcuts.html#objects">Keyboard shortcuts</a> for every tool key.</li></ul>',23)])])}const m=o(n,[["render",h]]);export{k as __pageData,m as default};
